static void
prof_backtrace_impl(void **vec, unsigned *len, unsigned max_len) {
	int nframes;

	cassert(config_prof);
	assert(*len == 0);
	assert(vec != NULL);
	assert(max_len <= PROF_BT_MAX_LIMIT);

	nframes = unw_backtrace(vec, max_len);
	if (nframes <= 0) {
		return;
	}
	*len = nframes;
}
